import { STRINGIFY_OPTIONS, stringify } from './vendor.mjs';

function repeatSpaces(count) {
  let result = '';
  for (let index = 0; index < count; index += 1) {
    result += ' ';
  }
  return result;
}

function trimTrailingNewline(text) {
  if (text.endsWith('\n')) {
    return text.slice(0, -1);
  }
  return text;
}

function escapeSingleQuotes(text) {
  let escaped = '';
  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];
    escaped += character;
    if (character === "'") {
      escaped += "'";
    }
  }
  return escaped;
}

function stripExpectedIndent(line, indent) {
  let index = 0;
  while (index < indent && index < line.length && line[index] === ' ') {
    index += 1;
  }
  return line.slice(index);
}

