  if (text.length === 0) {
    return 'plain';
  }

  const first = text[0];

  if (first === "'" || first === '"' || first === '|' || first === '>') {
    return 'quoted';
  }

  if (first === '!') {
    return 'tagged';
  }

  return 'plain';
}

function renderSimpleString(value) {
  return trimTrailingNewline(stringify(value, STRINGIFY_OPTIONS));
}

function renderMultilineString(value, baseIndent) {
  const parts = value.split('\n');
  const continuationIndent = repeatSpaces(baseIndent + 2);
  const lines = [`'${escapeSingleQuotes(parts[0])}`];

  for (let index = 1; index < parts.length; index += 1) {
    lines.push('');
    lines.push(`${continuationIndent}${escapeSingleQuotes(parts[index])}`);
  }

  lines[lines.length - 1] += "'";

  return { style: 'quoted', lines };
}

function normalizeExponent(text) {
  let exponentIndex = text.indexOf('e');
  if (exponentIndex === -1) {
    exponentIndex = text.indexOf('E');
  }

  if (exponentIndex === -1) {
    return text;
  }

  let mantissa = text.slice(0, exponentIndex);
  let exponent = text.slice(exponentIndex + 1);
  let sign = '+';

  if (exponent.length > 0 && (exponent[0] === '+' || exponent[0] === '-')) {
    sign = exponent[0];
    exponent = exponent.slice(1);
  }

  while (exponent.length < 2) {
    exponent = `0${exponent}`;
  }

  if (mantissa.indexOf('.') === -1) {
    mantissa = `${mantissa}.0`;
  }

  return `${mantissa.toLowerCase()}e${sign}${exponent}`;
}

function formatFloat(value) {
