  }

  if (node.kind === 'int') {
    return { style: 'plain', lines: [node.value.toString()] };
  }

  if (node.kind === 'float') {
    return { style: 'plain', lines: [formatFloat(node.value)] };
  }

  if (node.kind === 'timestamp') {
    return { style: 'plain', lines: [formatTimestampFromSource(node.source, node.value)] };
