function renderSetLines(node, indent) {
  if (node.items.length === 0) {
    return [`${repeatSpaces(indent)}!!set {}`];
  }

  const lines = [`${repeatSpaces(indent)}!!set`];
  for (const entry of node.items) {
    const keyText = renderKey(entry);
    lines.push(`${repeatSpaces(indent)}${keyText}: null`);
